<script setup>
import {ref,computed} from 'vue'
import Chart from './Chart.vue'
import PartitionDiagnostics from './PartitionDiagnostics.vue'
const props=defineProps({result:Object})
const emit=defineEmits(['experiment'])
function selectExperiment(row){const partitionParameters=JSON.parse(JSON.stringify(props.result.partitionParameters||{}));const parameters={...props.result.parameters};if(row.parameterScope&&row.parameterScope!=='basin'){partitionParameters[row.parameterScope]||={};partitionParameters[row.parameterScope][row.parameter]=row.value}else parameters[row.parameter]=row.value;emit('experiment',{parameters,partitionParameters})}
const year=ref('2024')
const diagnostics=computed(()=>props.result?.modelDiagnostics)
const years=computed(()=>[...new Set((diagnostics.value?.monthly||[]).map(m=>m.month.slice(0,4)))])
const months=computed(()=>(diagnostics.value?.monthly||[]).filter(m=>m.month.startsWith(year.value)))
const landStorage=computed(()=>{const m=months.value;const area=(props.result?.units||[]).reduce((n,u)=>n+u.areaKm2,0)*1000;return {unit:m.reduce((n,r)=>n+r.unitStorageChangeM3,0)/area,snow:m.reduce((n,r)=>n+r.snowStorageChangeM3,0)/area,route:m.reduce((n,r)=>n+r.routingStorageChangeM3,0)/area}})
const waterEquivalent=computed(()=>{let storage=0;const area=props.result?.diagnostics?.lakeAreaKm2*1e6;return months.value.map(m=>{storage+=m.lakeNetBalanceM3;return {date:m.month+'-01',change:m.lakeNetBalanceM3/area,cumulative:storage/area}})})
const sensitivityRows=computed(()=>[...(props.result?.sensitivity?.rows||[])].sort((a,b)=>a.parameter.localeCompare(b.parameter)||a.value-b.value))
const number=(v,n=2)=>v==null||!Number.isFinite(v)?'—':v.toLocaleString('zh-CN',{maximumFractionDigits:n})
const volume=v=>number(v==null?null:v/1e6)
const assessment=computed(()=>{const r=props.result,m=r?.metrics?.[year.value],rows=[];if(m?.flow.count){if(m.flow.logNse!=null&&m.flow.logNse<=0)rows.push('杜加log1p流量NSE为'+number(m.flow.logNse,3)+'：低流量及退水过程仍差于对数均值基准，不能只看普通NSE。');if(m.flow.pbias!=null&&Math.abs(m.flow.pbias)>20)rows.push('匹配观测日的径流总量偏差为'+number(m.flow.pbias,1)+'%，需联合核对降水偏差、融水和产流。20%仅为诊断提示，非业务验收线。')}if(r?.parameters?.lakeCoefficient>=1.5-1e-8)rows.push('湖面蒸发系数已到当前上界1.5，先核对全湖来水和蒸发基准，不应继续扩大系数来抵消残差。');rows.push('杜加仅约束其内部控制区，其余分区采用参数移用；单站流量拟合改善不保证全湖来水和湖位同步改善。');return rows})
const trace=computed(()=>props.result?.calibration?.trace||[])
const bestPath=computed(()=>{const values=trace.value.map(r=>r.bestObjective),lo=Math.min(...values),hi=Math.max(...values);return values.map((v,i)=>`${i?'L':'M'}${20+i/Math.max(1,values.length-1)*660},${135-(v-lo)/Math.max(hi-lo,1e-8)*110}`).join(' ')})
</script>
<template><section class="model-diagnostics">
 <div class="diagnostic-intro"><b>色林错：流域产汇流 → 入湖水量 → 湖泊收支</b><p>固定冰川边界，积雪与汇流全年连续。当前{{result.routingMode==='source-separated'?'壤中流和地下径流分别调蓄，再与地表及冰川来水进入河道':'采用原方案：合并径流后单库汇流'}}。杜加是扎加藏布内部断面，不重复计入入湖水量。</p></div>
 <div class="diagnostic-assessment"><b>{{year}} 年结构与资料提示</b><p v-for="text in assessment" :key="text">{{text}}</p></div>
 <template v-if="diagnostics"><div class="diagnostic-summary"><span>产流水量闭合 <b>{{number(diagnostics.landBalanceMaxErrorM3,8)}} m³</b></span><span>流域与汇流总闭合 <b>{{number(diagnostics.catchmentBalanceMaxErrorM3,8)}} m³</b></span><span>湖泊高程 <b>固定面积 · 可靠窗口内评价</b></span></div>
 <div class="form-row"><label>诊断年份<select v-model="year" aria-label="分区诊断年份"><option v-for="y in years" :key="y">{{y}}</option></select></label><span class="note">按年查看分区水量、杜加匹配过程与全湖收支</span></div><PartitionDiagnostics :diagnostics="diagnostics" :year="year"/>
 <h4>逐月水量账 <small>百万 m³ · 不同面积水深不能直接相加</small></h4><div class="form-row"><label>年份<select v-model="year" aria-label="水量诊断年份"><option v-for="y in years" :key="y">{{y}}</option></select></label></div><div class="table-wrap"><table><thead><tr><th>月份 / 覆盖</th><th>陆面降水</th><th>冰体外部供水</th><th>实际蒸散</th><th>土壤冰雪蓄水变化</th><th>汇流蓄水变化</th><th>总入湖</th><th>湖面降水</th><th>湖面蒸发</th><th>湖泊净收支</th></tr></thead><tbody><tr v-for="m in months" :key="m.month"><td>{{m.month}}<small class="block">{{m.complete?'完整月':m.hours+'小时·部分覆盖'}}</small></td><td>{{volume(m.landPrecipitationM3)}}</td><td>{{volume(m.iceExternalM3)}}</td><td>{{volume(m.landEvapotranspirationM3)}}</td><td>{{volume(m.unitStorageChangeM3)}}</td><td>{{volume(m.routingStorageChangeM3)}}</td><td>{{volume(m.lakeInflowM3)}}</td><td>{{volume(m.lakePrecipitationM3)}}</td><td>{{volume(m.lakeEvaporationM3)}}</td><td>{{volume(m.lakeNetBalanceM3)}}</td></tr></tbody></table></div>
 <p class="note">冰体外部供水为融冰与裸冰升华消耗的冰体质量。融雪是固态蓄水转移，已包含在径流中；全年湖泊净收支累计为相对水当量蓄水，冰期不解释为可靠水面高程。</p>
 <div class="storage-review"><b>{{year}} 年蓄水释放与预热检查</b><p>单元土壤／冰雪蓄水变化 <strong>{{number(landStorage.unit)}} mm</strong>，其中雪层 <strong>{{number(landStorage.snow)}} mm</strong>；汇流蓄水变化 <strong>{{number(landStorage.route)}} mm</strong>。均按全部陆域面积折算。</p><p>负值表示前期蓄水释放，可同时供给蒸散和径流；全年蒸散与径流不能只与当年降水比较。新起算默认三层张力水为容量的50%，续算继承父状态。2023一年预热不保证状态影响已经消失；解释率定改善时还需检查初始状态敏感性。</p></div>
 <h4>全年湖泊水当量变化 <small>m · 当前所选年份内累计</small></h4><Chart :rows="waterEquivalent" :series="[{key:'change',label:'当月净水量折合水深',type:'bar'},{key:'cumulative',label:'本年累计水当量变化'}]" unit="m"/><p class="note">按固定湖面积折算，逐月累计从所选年份首个模拟月开始，包含部分月时按实际覆盖累加；用于检查季节收支，不是实测或冰期可靠水面高程。冰期仍采用统一蒸发能力换算，尚未建立湖冰蒸发与升华过程。</p>
 <h4>可靠湖位窗口与未解释收支</h4><div class="table-wrap"><table><thead><tr><th>观测窗口</th><th>起点方式</th><th>观测蓄水变化</th><th>入湖水量</th><th>湖面降水</th><th>湖面蒸发</th><th>未解释净入水</th><th>等效湖位 m</th></tr></thead><tbody><tr v-for="w in diagnostics.lakeWindows" :key="w.id"><td>{{w.start.slice(0,10)}}<br>{{w.end.slice(0,10)}}</td><td>{{w.initialization==='first-reliable-subdaily-level'?'首个可靠分钟/小时观测':'日均水位锚定中午'}}</td><td>{{volume(w.residual?.observedStorageChangeM3)}}</td><td>{{volume(w.residual?.inflowM3)}}</td><td>{{volume(w.residual?.precipitationM3)}}</td><td>{{volume(w.residual?.evaporationM3)}}</td><td>{{volume(w.residual?.unexplainedNetInputM3)}}</td><td>{{number(w.residual?.unexplainedLevelChangeM,3)}}</td></tr></tbody></table></div><p class="note warning">窗口结果以实测起始湖位为条件，观测连续性不等于已核验无冰期，需结合现场或遥感冰情复核。未解释收支是资料和模型共同残差，不能直接认定为地下水。日均端点采用日中近似、端点半权重；不能代替逐时水量闭合检查。缺少完整气象端点时不估算残差。</p></template><p v-else class="note">此成果来自旧版本，未保存新的月度诊断；保留原成果，可恢复条件后重新计算。</p>
 <template v-if="result.calibration"><h4>率定目标与收敛过程</h4><p class="note">目标 {{result.calibration.objectiveProfile||'原方案'}} · 权重 {{JSON.stringify(result.calibration.objectiveWeights||{})}} · 仅用2024观测。{{result.calibration.evaluations}}次候选，{{result.calibration.converged?'达到停止判据':result.calibration.termination==='proposal-limit'?'达到候选约束上限':'预算耗尽'}}；停止判据不代表全局最优。</p><svg v-if="trace.length" class="calibration-trace" viewBox="0 0 700 165" role="img" aria-label="率定历史最优目标值，越低越好"><path d="M20 15V140H685"/><path :d="bestPath" class="best-trace"/><text x="20" y="160">1次</text><text x="610" y="160">{{trace.length}}次</text><text x="25" y="20">{{number(trace[0].bestObjective,4)}}</text><text x="570" y="25">最优 {{number(trace.at(-1).bestObjective,4)}}</text></svg></template>
 <p v-if="result.sensitivity?.skipped?.length" class="note warning">{{result.sensitivity.skipped.length}}个扰动违反参数联合约束，已跳过，其余实验保留。</p><template v-if="result.sensitivity"><h4>逐参数局部扰动 · 2024年</h4><p class="note">每次仅改变一个参数，其余条件不变。负的目标变化或湖位RMSE变化表示该目标改善。按参数分组展示，不作流量与湖位的综合优劣排序。该实验不确定最优参数，也未将扰动自动应用到参数库。</p><div class="table-wrap"><table><thead><tr><th>参数</th><th>原值 → 扰动值</th><th>流量目标变化</th><th>NSE变化</th><th>PBIAS变化 %</th><th>湖位RMSE变化 m</th><th>试调</th></tr></thead><tbody><tr v-for="(r,i) in sensitivityRows" :key="i"><td>{{r.label}}</td><td>{{number(r.baselineValue,4)}} → {{number(r.value,4)}}</td><td>{{number(r.flowObjectiveChange,4)}}</td><td>{{number(r.flowNseChange,4)}}</td><td>{{number(r.flowBiasChange,2)}}</td><td>{{number(r.lakeRmseChangeM,4)}}</td><td><button @click="selectExperiment(r)">带入人工试调</button></td></tr></tbody></table></div></template>
</section></template>
<style scoped>
.model-diagnostics h4{font-size:14px;margin:23px 0 12px}.model-diagnostics h4 small{font-size:11px;color:#71828c;font-weight:400}.diagnostic-intro{border-left:3px solid #277e83;padding:12px 16px;background:#f4f8f8}.diagnostic-intro p{color:#647981;font-size:12px;line-height:1.9;margin:6px 0 0}.diagnostic-summary{display:flex;gap:20px;flex-wrap:wrap;margin:17px 0}.diagnostic-summary span{display:grid;gap:7px;font-size:11px;color:#637e83}.diagnostic-summary b{font-size:13px;color:#296e77}.model-diagnostics td{font-variant-numeric:tabular-nums;font-size:11px;white-space:nowrap}.calibration-trace{width:100%;height:165px;background:#f6f9f9}.calibration-trace path{fill:none;stroke:#bdced0;stroke-width:1}.calibration-trace .best-trace{stroke:#217f88;stroke-width:2}.calibration-trace text{font-size:11px;fill:#668087}
.diagnostic-assessment{margin:12px 0;padding:12px 16px;border-left:2px solid #bb914c;background:#fbf8f1;font-size:12px;color:#80693e}.diagnostic-assessment p{margin:7px 0 0;line-height:1.8}
.storage-review{border-left:3px solid #8a9d64;background:#f5f7ef;padding:14px 17px;margin:18px 0;color:#5d7048;font-size:12px}.storage-review p{line-height:1.9;margin:8px 0 0}.storage-review strong{font-variant-numeric:tabular-nums}
</style>
